import static org.junit.Assert.assertNotSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ConstructorInstantiator#newInstance
 */
public class ConstructorInstantiator_newInstance_TriageGen1Test {

    // Mock class for testing
    public static class TestClass {
        public TestClass() {}
    }

    // Inner class to spy on the class under test since we need to mock its internal methods
    // noArgConstructor and withOuterClass are likely protected/package-private
    public static class SpyConstructorInstantiator extends ConstructorInstantiator {
        public SpyConstructorInstantiator(Object outerClassInstance) {
            super(outerClassInstance);
        }

        // We override/mock these because they are part of the logic being tested
        // in the provided snippet.
        @SuppressWarnings("unchecked")
        public <T> T noArgConstructor(Class<T> cls) {
            return null; 
        }

        @SuppressWarnings("unchecked")
        public <T> T withOuterClass(Class<T> cls) {
            return null;
        }
    }

    @Test
    @SuppressWarnings("unchecked")
    public void testNewInstance_WhenOuterClassInstanceIsNull_CallsNoArgConstructor() {
        // Arrange
        // We use a spy to control the behavior of the methods called inside newInstance
        SpyConstructorInstantiator instantiator = spy(new SpyConstructorInstantiator(null));
        TestClass expectedInstance = new TestClass();

        doReturn(expectedInstance).when(instantiator).noArgConstructor(TestClass.class);

        // Act
        TestClass result = instantiator.newInstance(TestClass.class);

        // Assert
        assertEquals(expectedInstance, result);
        // Verify the branch: if (outerClassInstance == null)
    }

    @Test
    @SuppressWarnings("unchecked")
    public void testNewInstance_WhenOuterClassInstanceIsNotNull_CallsWithOuterClass() {
        // Arrange
        Object outerInstance = new Object();
        SpyConstructorInstantiator instantiator = spy(new SpyConstructorInstantiator(outerInstance));
        TestClass expectedInstance = new TestClass();

        doReturn(expectedInstance).when(instantiator).withOuterClass(TestClass.class);

        // Act
        TestClass result = instantiator.newInstance(TestClass.class);

        // Assert
        assertEquals(expectedInstance, result);
        // Verify the branch: else { return withOuterClass(cls); }
    }
}
